const b64 = x => Buffer.from(x).toString("base64url");
async function auth() {
 const c = JSON.parse(process.env.GOOGLE_MERCHANT_SERVICE_ACCOUNT_JSON||"{}");
 if(c.type!=="service_account"||!c.private_key||!c.client_email) throw Error("Missing service account credential fields");
 const now=Math.floor(Date.now()/1000);
 const unsigned=b64(JSON.stringify({alg:"RS256",typ:"JWT"}))+"."+b64(JSON.stringify({iss:c.client_email,scope:"https://www.googleapis.com/auth/content",aud:"https://oauth2.googleapis.com/token",iat:now,exp:now+3600}));
 const signer=createSign("RSA-SHA256");signer.update(unsigned);signer.end();
 const assertion=unsigned+"."+b64(signer.sign(c.private_key));
 const result=await fetch("https://oauth2.googleapis.com/token",{method:"POST",headers:{"content-type":"application/x-www-form-urlencoded"},body:new URLSearchParams({grant_type:"urn:ietf:params:oauth:grant-type:jwt-bearer",assertion}),signal:AbortSignal.timeout(20000)});
 if(!result.ok)throw Error("Google OAuth HTTP "+result.status);
 const response=await result.json();
 if(!response.access_token)throw Error("Google OAuth access token missing");
 return response.access_token;
}

async function check(p){
 const link="https://shop.ynotworld.app/products/"+p.handle;
 let jsonVerified=false,htmlVerified=false;
 try {
 const res=await fetch(link+".js",{redirect:"follow",signal:AbortSignal.timeout(12000)});
 if(res.ok&&new URL(res.url).hostname==="shop.ynotworld.app"){
   const d=await res.json();
   const prices=(d.variants||[]).map(v=>Number(v.price));
   jsonVerified=d.title?.trim().toLowerCase()===p.title.trim().toLowerCase()&&prices.includes(Math.round(p.price*100))&&(d.variants||[]).some(v=>v.available===true);
 }
 }catch{}
 if(!jsonVerified){
  try{
   const res=await fetch(link,{redirect:"follow",headers:{"user-agent":"Googlebot"},signal:AbortSignal.timeout(14000)});
   if(res.ok&&new URL(res.url).hostname==="shop.ynotworld.app"){
    const html=(await res.text()).slice(0,240000);
    htmlVerified=html.toLowerCase().includes(p.title.slice(0,14).toLowerCase())&&html.includes(p.price.toFixed(2));
   }
  }catch{}
 }
 if(jsonVerified||htmlVerified)return {...p,link,verifiedBy:jsonVerified?"shopify_json":"storefront_html"};
 return null;
}
async function main(){
 if(process.env.VERCEL_ENV!=="preview"||process.env.GOOGLE_MERCHANT_ACCOUNT_ID!==project||process.env.GOOGLE_MERCHANT_DATA_SOURCE_ID!==source)return console.log("MERCHANT_MORE skipped: environment mismatch");
 console.log("MERCHANT_MORE candidates="+products.length);
 let verified=[];
 for(let i=0;i<products.length;i+=8){const batch=await Promise.all(products.slice(i,i+8).map(check));verified.push(...batch.filter(Boolean));}
 console.log("MERCHANT_MORE storefront_verified="+verified.length+" withheld="+(products.length-verified.length)+" json="+verified.filter(v=>v.verifiedBy==="shopify_json").length+" html="+verified.filter(v=>v.verifiedBy==="storefront_html").length);
 if(!verified.length)return;
verified=verified.slice(0,150);
 let token;try{token=await auth()}catch(e){return console.log("MERCHANT_MORE oauth_error="+String(e.message).slice(0,120))}
 console.log("MERCHANT_MORE oauth_ok");
 let inserted=0,rejected=0,failed=0;
 async function send(p){
 const input={offerId:p.offerId,contentLanguage:"en",feedLabel:"FR",productAttributes:{title:p.title,description:p.description,link:p.link,imageLink:p.image,availability:"IN_STOCK",price:{amountMicros:String(Math.round(p.price*1e6)),currencyCode:"EUR"},shipping:[{country:"FR",service:"Standard",price:{amountMicros:"7990000",currencyCode:"EUR"}}]}};
 try{
 const url="https://merchantapi.googleapis.com/products/v1/accounts/"+project+"/productInputs:insert?dataSource=accounts/"+project+"/dataSources/"+source;
 const res=await fetch(url,{method:"POST",headers:{"authorization":"Bearer "+token,"content-type":"application/json"},body:JSON.stringify(input),signal:AbortSignal.timeout(22000)});
 if(res.ok){inserted++;console.log("MERCHANT_MORE accepted "+p.offerId)}
 else{rejected++;const b=await res.json().catch(()=>({}));console.log("MERCHANT_MORE rejected "+p.offerId+" HTTP="+res.status+" code="+String(b.error?.status||"unknown"))}
 }catch(e){failed++;console.log("MERCHANT_MORE failed "+p.offerId+" reason="+(e?.name||"network"));}
 }
 for(let i=0;i<verified.length;i+=5){await Promise.all(verified.slice(i,i+5).map(send));await new Promise(r=>setTimeout(r,400));}
 console.log("MERCHANT_MORE COMPLETE candidates="+products.length+" verified="+verified.length+" accepted="+inserted+" rejected="+rejected+" failed="+failed);
}
await main();
